/**
 * Read len bytes at offset a from a treefiles export. Reads are clamped to
 * the end of the TREEPAGESIZE block containing a; missing block files read
 * as zeroes.
 */
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
    off_t blockoff = a % TREEPAGESIZE;
    size_t chunk = TREEPAGESIZE - blockoff;
    if (chunk > len) chunk = len;
    int fd = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->treefile_lock);
    if (fd < 0) {
        if (errno == ENOENT) { memset(buf, 0, chunk); return chunk; }
        return -1;
    }
    ssize_t ret = pread(fd, buf, chunk, blockoff);
    int saved_errno = errno;
    close(fd);
    errno = saved_errno;
    if (ret < 0) return -1;
    /* Block files may be shorter than TREEPAGESIZE; missing tail reads as zeroes */
    if ((size_t)ret < chunk) memset(buf + ret, 0, chunk - ret);
    return chunk;
}
```

