 * @param name the name of the tree root (i.e., the exportname), also
 * used as the buffer the constructed path is written to
 * @param lenmax the size of the name buffer
 * @param size the total size of the exported device
 * @param pos the position in the device to construct the path for
 * @param ppos if non-NULL, the offset of pos within its block file is
 * written here
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	off_t scale = 1;
	int len = strlen(name);
	int i;

	if (ppos)
		*ppos = pos % TREEPAGESIZE;
	if (lenmax <= 0 || len >= lenmax)
		return;

	for (i = 0; i < depth; i++)
		scale *= TREEDIRSIZE;
	for (i = depth; i >= 1; i--) {
		int written = snprintf(name + len, lenmax - len, "/TREE%04d",
				(int)((block / scale) % TREEDIRSIZE));
		if (written < 0 || written >= lenmax - len) {
			name[lenmax - 1] = '\0';
			DEBUG("constructed tree path is too long\n");
			return;
		}
		len += written;
		scale /= TREEDIRSIZE;
	}
	if (snprintf(name + len, lenmax - len, "/FILE%04d",
			(int)(block % TREEDIRSIZE)) >= lenmax - len) {
		name[lenmax - 1] = '\0';
		DEBUG("constructed tree path is too long\n");
	}
}

/**
 * Create the directory in path, along with any missing parent
 * directories. Existing directories are left alone, so this is safe
 * to call concurrently and on paths that already exist.
 *
 * @param path the directory to create
 **/
void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			if (mkdir(path, 0700) < 0 && errno != EEXIST) {
				*p = '/';
				return;
			}
			*p = '/';
		}
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST)
		return;
}

/**
 * Open the block file holding the data at a given position of a
 * treefiles export, creating the directories leading up to it when
 * the caller asked for the file to be created.
 *
 * @param name the name of the tree root (i.e., the exportname)
 * @param mode flags for open(); O_CREAT must be included if the file
 * (and the directories leading to it) should be created when missing
 * @param size the total size of the exported device
 * @param pos the position in the device whose block file to open
 * @param mutex if non-NULL, locked while the tree is being modified
 * @return a file descriptor on success, or -1 (with errno set) on
 * failure; a missing block file results in errno being ENOENT
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	size_t namelen = strlen(name);
	char *leaf;
	int fd;

	if (namelen >= sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	memcpy(path, name, namelen + 1);
	construct_path(path, sizeof(path), size, pos, NULL);

	if (mutex)
		pthread_mutex_lock(mutex);
	fd = open(path, mode, 0600);
	if (fd < 0 && errno == ENOENT && (mode & O_CREAT)) {
		leaf = strrchr(path, '/');
		if (leaf != NULL) {
			*leaf = '\0';
			mkdir_path(path);
			*leaf = '/';
		}
		fd = open(path, mode, 0600);
	}
	if (mutex)
		pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at a given position of a
 * treefiles export, pruning any directories that become empty as a
 * result (except for the root of the tree itself). Deleting a block
 * that has no file is a no-op.
 *
 * @param name the name of the tree root (i.e., the exportname)
 * @param size the total size of the exported device
 * @param pos the position in the device whose block file to delete
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	size_t namelen = strlen(name);
	char *slash;

	if (namelen >= sizeof(path))
		return;
	memcpy(path, name, namelen + 1);
	construct_path(path, sizeof(path), size, pos, NULL);

	if (unlink(path) < 0)
		return;

	/* prune directories that have become empty, but never the tree
	 * root itself */
	for (;;) {
		slash = strrchr(path, '/');
		if (slash == NULL || (size_t)(slash - path) <= namelen)
			break;
		*slash = '\0';
		if (rmdir(path) < 0) {
			*slash = '/';
			break;
		}
	}
}

