/**
 * Read an amount of bytes at a given offset from a treefiles export.
 * Reads are limited to the TREEPAGESIZE block containing the offset,
 * so the caller can loop over the blocks of a larger request. Block
 * files that do not exist read as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes handled, or -1 in case of an error
 **/
ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t offset = a % TREEPAGESIZE;
	size_t blen = TREEPAGESIZE - offset;
	int fd;
	ssize_t retval;

	if(blen > len)
		blen = len;

	DEBUG("(TREE-READ at offset %llu len %u), ", (long long unsigned)a, (unsigned int)blen);

	fd = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->treefile_lock);
	if(fd < 0) {
		if(errno == ENOENT) {
			/* the block was never written, so it reads as
			 * zeroes */
			memset(buf, '\0', blen);
			return blen;
		}
		return -1;
	}
	retval = pread(fd, buf, blen, offset);
	if(retval < 0) {
		int saved_errno = errno;
		close(fd);
		errno = saved_errno;
		return -1;
	}
	/* block files may be shorter than TREEPAGESIZE; the part beyond
	 * their end reads as zeroes */
	memset(buf + retval, '\0', blen - retval);
	close(fd);

	return blen;
}

