		DEBUG("TRIM is not yet supported for copy-on-write exports");
		return 0;
	}
	FILE_INFO cur = ...
```

Add the treefiles branch. Required headers for nbdsrv.c: fcntl.h (O_RDWR), errno.h — checking the current includes: assert.h, ctype.h, netdb.h, stdlib.h, stdio.h, string.h, syslog.h, unistd.h, pthread.h, sys/stat.h, sys/types.h, sys/socket.h, backend.h, sys/ioctl.h (conditional), sys/mount.h (conditional), cliserv.h. No fcntl.h, no errno.h either (string.h doesn't declare errno). Add #include <errno.h> and <fcntl.h>, plus "treefiles.h".

Trim logic:
```c
if(client->server->flags & F_TREEFILES) {
	/* A trimmed block no longer holds data, so its block file can
	 * be removed. Fully trimmed blocks are deleted, while partially
	 * trimmed blocks are overwritten with zeros so that they read
	 * back as zeros. */
	char zeros[TREEPAGESIZE];
	off_t end = req->from + req->len;
	off_t blockstart;
	off_t from;

	memset(zeros, '\0', sizeof(zeros));
	from = req->from;
	blockstart = (from / TREEPAGESIZE) * TREEPAGESIZE;
	for(; blockstart < end; blockstart += TREEPAGESIZE) {
		off_t inblk = from - blockstart;
		off_t blen = TREEPAGESIZE - inblk;
		if(blen > end - (blockstart + inblk))
			blen = end - (blockstart + inblk);
		if(inblk == 0 && blen == TREEPAGESIZE) {
			delete_treefile(client->exportname, client->exportsize, blockstart);
		} else {
			int fd = open_treefile(client->exportname, O_RDWR, client->exportsize, blockstart, &client->treefile_lock);
			if(fd >= 0) {
				if(pwrite(fd, zeros + inblk, blen, inblk) != blen) {
					int saved_errno = errno;
					close(fd);
					errno = saved_errno;
					return -1;
				}
				close(fd);
			} else if(errno != ENOENT) {
				return -1;
			}
		}
	}
	DEBUG("Performed a treefiles TRIM request from %llu for %llu bytes", (unsigned long long)req->from, (unsigned long long)req->len);
	return 0;
}
```

Wait: `pwrite(fd, zeros + inblk, blen, inblk)` — zeros+inblk is the same as zeros (since it's zero anyway), but writing from zeros[0] with length blen is enough. Use pwrite(fd, zeros, blen, inblk).

Note: `from` is used for inblk on the first block, and on subsequent blocks inblk = from - blockstart, but there from < blockstart → negative value! Bug: inblk must be max(0, from - blockstart). Let's restructure: only the first block can be partial on the leading side. Simply: inblk = (from > blockstart) ? from - blockstart : 0. Since from is fixed and blockstart increases, for the first block from >= blockstart (because blockstart = floor(from/TP)*TP), and for subsequent blocks from < blockstart → inblk=0. Good.

Also, the tail of the last block: blen gets clamped by end. The trailing block may also be partial (end not block-aligned). Handled by the same formula.

C-style declaration: declare at the top of the block. In C89-ish style this codebase uses: declare at the top of the block. The existing exptrim declares `FILE_INFO cur` mid-function after statements (a C99-ish style used in this file — "FILE_INFO cur = g_array_index(...)" appears after an if statement). So mid-block declaration is OK.

One concern: `char zeros[TREEPAGESIZE]` = 4KB on the stack — no problem (there's already a precedent with pagebuf[DIFFPAGESIZE] in expwrite).

OK, let's apply the edit to nbdsrv.c.

