int exptrim(struct nbd_request* req, CLIENT* client) {
	/* Caller did range checking */
	assert(!(client->server->flags & F_READONLY));
	assert(req->from + req->len <= client->exportsize);
	/* For copy-on-write, we should trim on the diff file. Not yet
	 * implemented. */
	if(client->server->flags & F_COPYONWRITE) {
		DEBUG("TRIM not supported yet on copy-on-write exports");
		return 0;
	}
	if(client->server->flags & F_TREEFILES) {
		/* A trimmed block no longer holds data, so the file
		 * it lives in can go. Blocks covered by the request
		 * entirely are deleted; partially covered blocks are
		 * zeroed, so they still read back as zeroes. */
		char zeros[TREEPAGESIZE];
		off_t from = req->from;
		off_t end = req->from + req->len;
		off_t blockstart = (from / TREEPAGESIZE) * TREEPAGESIZE;

		memset(zeros, '\0', sizeof(zeros));
		for(; blockstart < end; blockstart += TREEPAGESIZE) {
			off_t inblk = from > blockstart ? from - blockstart : 0;
			off_t blen = TREEPAGESIZE - inblk;

			if(blen > end - (blockstart + inblk))
				blen = end - (blockstart + inblk);
			if(inblk == 0 && blen == TREEPAGESIZE) {
				delete_treefile(client->exportname, client->exportsize, blockstart);
			} else {
				int fd = open_treefile(client->exportname, O_RDWR, client->exportsize, blockstart, &client->treefile_lock);

				if(fd >= 0) {
					ssize_t ret = pwrite(fd, zeros, blen, inblk);
					int saved_errno = errno;
					close(fd);
					if(ret != blen) {
						errno = saved_errno;
						return -1;
					}
				} else if(errno != ENOENT) {
					/* a missing file just reads back as zeroes */
					return -1;
				}
			}
		}
		DEBUG("Performed treefiles TRIM request from %llu to %llu", (unsigned long long) req->from, (unsigned long long) req->len);
		return 0;
	}
	FILE_INFO cur = g_array_index(client->export, FILE_INFO, 0);

