					}
				} else if(errno != ENOENT) {
					/* a missing file just reads back as zeroes */
					return -1;
				}
			}
		}
		DEBUG("Performed treefiles TRIM request from %llu to %llu", (unsigned long long) req->from, (unsigned long long) req->len);
