args.content:
#include <lfs.h>

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include <nbdsrv.h>
#include <treefiles.h>
#include "macro.h"

static char root[256];

static void reset_root(void) {
	/* construct_path() appends to the root name, so restore it
	 * before every use */
	snprintf(root, sizeof(root), "%s/export", workdir);
}

static char workdir[256];

static int file_exists(const char *path) {
	struct stat st;

	return stat(path, &st) == 0 && S_ISREG(st.st_mode);
}

static int dir_exists(const char *path) {
	struct stat st;

	return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

int main(void) {
	char expected[512];
	char buf[TREEPAGESIZE];
	struct nbd_request req;
	SERVER srv;
	CLIENT cl;
	off_t ppos;
	int fd;
	int i;

	snprintf(workdir, sizeof(workdir), "/tmp/nbd-treefiles-XXXXXX");
	count_assert(mkdtemp(workdir) != NULL);

	/* a 4MB device holds exactly TREEDIRSIZE blocks, which all fit
	 * in the root of the tree */
	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 0, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE0000", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == 0);

	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 5*TREEPAGESIZE+100, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE0005", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == 100);

	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 4*1024*1024-1, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE1023", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == TREEPAGESIZE-1);

	/* a 4GB device needs one extra level of TREEXXXX directories */
	reset_root();
	construct_path(root, sizeof(root), 4LL*1024*1024*1024, 0, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0000/FILE0000", workdir);
	count_assert(strcmp(root, expected) == 0);

	reset_root();
	construct_path(root, sizeof(root), 4LL*1024*1024*1024, 2000LL*TREEPAGESIZE, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0001/FILE0976", workdir);
	count_assert(strcmp(root, expected) == 0);

	/* a 4TB device needs two levels of TREEXXXX directories */
	reset_root();
	construct_path(root, sizeof(root), 4LL*1024*1024*1024*1024,
			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0003/TREE0007/FILE0005", workdir);
	count_assert(strcmp(root, expected) == 0);

	/* mkdir_path() creates missing parent directories */
	snprintf(buf, sizeof(buf), "%s/a/b/c", workdir);
	mkdir_path(buf);
	count_assert(dir_exists(buf));
	/* calling it again on an existing path must not fail */
	mkdir_path(buf);
	count_assert(dir_exists(buf));

	/* a block that was never written has no file */
	reset_root();
	count_assert(open_treefile(root, O_RDONLY, 4*1024*1024, 0, NULL) == -1);
	count_assert(errno == ENOENT);

	/* open_treefile() creates the file (and its parents) on demand */
	reset_root();
	fd = open_treefile(root, O_RDWR | O_CREAT, 4LL*1024*1024*1024,
			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE, NULL);
	count_assert(fd >= 0);
	memset(buf, 'A', TREEPAGESIZE);
	count_assert(pwrite(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	close(fd);
	snprintf(expected, sizeof(expected), "%s/export/TREE0003/TREE0007/FILE0005", workdir);
	count_assert(file_exists(expected));

	/* the data can be read back through another handle */
	reset_root();
	fd = open_treefile(root, O_RDONLY, 4LL*1024*1024*1024,
			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE+10, NULL);
	count_assert(fd >= 0);
	memset(buf, 0, TREEPAGESIZE);
	count_assert(pread(fd, buf, 10, 0) == 10);
	count_assert(buf[0] == 'A' && buf[9] == 'A');
	close(fd);

	/* delete_treefile() removes the file and prunes the empty
	 * directories, but not the root of the tree */
	reset_root();
	delete_treefile(root, 4LL*1024*1024*1024,
			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE);
	count_assert(!file_exists(expected));
	count_assert(!dir_exists(expected + 0) || 1); /* keep gcc happy */
	snprintf(buf, sizeof(buf), "%s/export/TREE0003/TREE0007", workdir);
	count_assert(!dir_exists(buf));
	snprintf(buf, sizeof(buf), "%s/export/TREE0003", workdir);
	count_assert(!dir_exists(buf));
	count_assert(dir_exists(expected + 0) || 1); /* keep gcc happy */
	snprintf(buf, sizeof(buf), "%s/export", workdir);
	count_assert(dir_exists(buf));
	/* deleting the block again is a no-op */
	reset_root();
	delete_treefile(root, 4LL*1024*1024*1024,
			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE);

	/* set up a treefiles export and verify that TRIM deletes fully
	 * covered blocks and zeroes partially covered ones */
	memset(&srv, 0, sizeof(srv));
	srv.exportname = workdir;
	srv.flags = F_TREEFILES;
	memset(&cl, 0, sizeof(cl));
	cl.exportsize = 4*1024*1024;
	cl.exportname = root;
	cl.server = &srv;
	pthread_mutex_init(&cl.lock, NULL);
	pthread_mutex_init(&cl.treefile_lock, NULL);
	reset_root();

	for (i = 0; i < 3; i++) {
		fd = open_treefile(root, O_RDWR | O_CREAT, cl.exportsize, i*TREEPAGESIZE, &cl.treefile_lock);
		count_assert(fd >= 0);
		memset(buf, 'A'+i, TREEPAGESIZE);
		count_assert(pwrite(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
		close(fd);
	}

	/* trim blocks 0 and 1 entirely, and block 2 only in part */
	req.magic = NBD_REQUEST_MAGIC;
	req.type = NBD_CMD_TRIM;
	req.from = 0;
	req.len = 2*TREEPAGESIZE+1024;
	count_assert(exptrim(&req, &cl) == 0);

	snprintf(expected, sizeof(expected), "%s/export/FILE0000", workdir);
	count_assert(!file_exists(expected));
	snprintf(expected, sizeof(expected), "%s/export/FILE0001", workdir);
	count_assert(!file_exists(expected));
	snprintf(expected, sizeof(expected), "%s/export/FILE0002", workdir);
	count_assert(file_exists(expected));
	fd = open(expected, O_RDONLY, 0);
	count_assert(fd >= 0);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	close(fd);
	/* the part of block 2 before the trim still holds its data */
	count_assert(buf[0] == 'C' && buf[1023] == 'C');
	/* the trimmed part of block 2 reads back as zeroes */
	count_assert(buf[1024] == '\0' && buf[2047] == '\0');

	return 0;
}

