	req.magic = NBD_REQUEST_MAGIC;
	req.type = NBD_CMD_TRIM;
	req.from = 0;
	req.len = 2*TREEPAGESIZE+1024;
	count_assert(exptrim(&req, &cl) == 0);

	snprintf(expected, sizeof(expected), "%s/export/FILE0000", workdir);
	count_assert(!file_exists(expected));
	snprintf(expected, sizeof(expected), "%s/export/FILE0001", workdir);
	count_assert(!file_exists(expected));
	snprintf(expected, sizeof(expected), "%s/export/FILE0002", workdir);
	count_assert(file_exists(expected));
	fd = open(expected, O_RDONLY, 0);
	count_assert(fd >= 0);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	close(fd);
	/* the part of block 2 before the trim still holds its data */
	count_assert(buf[0] == 'C' && buf[1023] == 'C');
	/* the trimmed part of block 2 reads back as zeroes */
	count_assert(buf[1024] == '\0' && buf[2047] == '\0');

	return 0;
}

