#include <lfs.h>

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include <nbdsrv.h>
#include <treefiles.h>
#include "macro.h"

static char workdir[256];
static char root[256];

static void reset_root(void) {
	/* construct_path() appends to the root name, so restore it
	 * before every use */
	snprintf(root, sizeof(root), "%s/export", workdir);
}

static int file_exists(const char *path) {
	struct stat st;

	return stat(path, &st) == 0 && S_ISREG(st.st_mode);
}

static int dir_exists(const char *path) {
	struct stat st;

	return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

int main(void) {
	char expected[512];
	char buf[TREEPAGESIZE];
	struct nbd_request req;
	SERVER srv;
	CLIENT cl;
	off_t ppos;
	int fd;
	int i;

	snprintf(workdir, sizeof(workdir), "/tmp/nbd-treefiles-XXXXXX");
	count_assert(mkdtemp(workdir) != NULL);

	/* a 4MB device holds exactly TREEDIRSIZE blocks, which all fit
	 * in the root of the tree */
	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 0, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE0000", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == 0);

	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 5*TREEPAGESIZE+100, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE0005", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == 100);

	reset_root();
	construct_path(root, sizeof(root), 4*1024*1024, 4*1024*1024-1, &ppos);
	snprintf(expected, sizeof(expected), "%s/export/FILE1023", workdir);
	count_assert(strcmp(root, expected) == 0);
	count_assert(ppos == TREEPAGESIZE-1);

	/* a 4GB device needs one extra level of TREEXXXX directories */
	reset_root();
	construct_path(root, sizeof(root), 4LL*1024*1024*1024, 0, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0000/FILE0000", workdir);
	count_assert(strcmp(root, expected) == 0);

	reset_root();
	construct_path(root, sizeof(root), 4LL*1024*1024*1024, 2000LL*TREEPAGESIZE, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0001/FILE0976", workdir);
	count_assert(strcmp(root, expected) == 0);

