			((3LL*TREEDIRSIZE+7)*TREEDIRSIZE+5)*TREEPAGESIZE, NULL);
	snprintf(expected, sizeof(expected), "%s/export/TREE0003/TREE0007/FILE0005", workdir);
	count_assert(strcmp(root, expected) == 0);

