	count_assert(fd >= 0);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	close(fd);
	/* the trimmed part of block 2 reads back as zeroes */
	count_assert(buf[0] == '\0' && buf[1023] == '\0');
	/* the part of block 2 beyond the trim still holds its data */
	count_assert(buf[1024] == 'C' && buf[TREEPAGESIZE-1] == 'C');

	return 0;
}

