                int retval = 0;

                /* Block files are opened per request, so their data
                 * has been handed to the filesystem already; syncing
                 * the tree root is all that is left to do here. */
                fd = open(client->exportname, O_RDONLY);
                if (fd >= 0) {
                        retval = fsync(fd);
                        close(fd);
                }
                return retval;
        }

        if (client->server->flags & F_WAIT) {
                return fsync(client->difffile);
        }

        for (i = 0; i < client->export->len; i++) {
                FILE_INFO fi = g_array_index(client->export, FILE_INFO, i);
                if (fsync(fi.fhandle) < 0)
                        return -1;
        }

        return 0;
}

